import firebase_admin
from firebase_admin import credentials
from firebase_admin import auth
import os

def initialize_firebase_app():
    if not firebase_admin._apps:
        # Use a service account file from an environment variable, or default to a local file
        service_account_path = os.getenv("FIREBASE_SERVICE_ACCOUNT_PATH", "path/to/your/serviceAccountKey.json")
        try:
            cred = credentials.Certificate(service_account_path)
            firebase_admin.initialize_app(cred)
            print("Firebase Admin SDK initialized successfully.")
        except Exception as e:
            print(f"Error initializing Firebase Admin SDK: {e}")
            raise
    return firebase_admin.get_app()

def get_firebase_auth_client():
    app = initialize_firebase_app()
    return auth

import requests
import os
from identity_models import LoginPayload

def email_password_login(payload: LoginPayload):
    api_key = os.getenv("FIREBASE_WEB_API_KEY")
    if not api_key:
        raise ValueError("FIREBASE_WEB_API_KEY environment variable not set.")

    rest_api_url = f"https://identitytoolkit.googleapis.com/v1/accounts:signInWithPassword?key={api_key}"
    headers = {"Content-Type": "application/json"}
    data = {
        "email": payload.email,
        "password": payload.password,
        "returnSecureToken": True
    }

    response = requests.post(rest_api_url, headers=headers, json=data)
    response.raise_for_status()
    return response.json()

import requests
import os
from identity_models import RefreshSessionPayload

def refresh_session(payload: RefreshSessionPayload):
    api_key = os.getenv("FIREBASE_WEB_API_KEY")
    if not api_key:
        raise ValueError("FIREBASE_WEB_API_KEY environment variable not set.")

    rest_api_url = f"https://securetoken.googleapis.com/v1/token?key={api_key}"
    headers = {"Content-Type": "application/json"}
    data = {
        "grant_type": "refresh_token",
        "refresh_token": payload.refresh_token
    }

    response = requests.post(rest_api_url, headers=headers, json=data)
    response.raise_for_status()
    return response.json()

import requests
import os
from identity_models import PasswordResetPayload

def password_reset(payload: PasswordResetPayload):
    api_key = os.getenv("FIREBASE_WEB_API_KEY")
    if not api_key:
        raise ValueError("FIREBASE_WEB_API_KEY environment variable not set.")

    rest_api_url = f"https://identitytoolkit.googleapis.com/v1/accounts:sendOobCode?key={api_key}"
    headers = {"Content-Type": "application/json"}
    data = {
        "requestType": "PASSWORD_RESET",
        "email": payload.email
    }

    response = requests.post(rest_api_url, headers=headers, json=data)
    response.raise_for_status()
    return response.json()
